export const tips = [
  // Month 1
  { id: 1, month: 1, style: 'gentle', topic: 'development', title: 'Skin-to-Skin Contact', body: 'Hold your newborn skin-to-skin as much as possible. It regulates their temperature, heart rate, and supports bonding and breastfeeding.', source: 'AAP' },
  { id: 2, month: 1, style: 'gentle', topic: 'development', title: 'Respond to Every Cry', body: 'You cannot spoil a newborn. Responding promptly to cries builds trust and a secure attachment foundation.', source: 'AAP' },
  { id: 3, month: 1, style: 'schedule', topic: 'sleep', title: 'Eat, Play, Sleep Cycle', body: 'Start a simple eat → play → sleep rhythm during the day to gently introduce predictability without strict scheduling.', source: 'Pediatric Sleep Council' },
  { id: 4, month: 1, style: 'schedule', topic: 'feeding', title: 'Track Feeds and Diapers', body: 'Log feeding times and wet/dirty diapers to ensure adequate intake. Newborns should have 6–8 wet diapers per day.', source: 'AAP' },

  // Month 2
  { id: 5, month: 2, style: 'gentle', topic: 'development', title: 'Talk and Sing Often', body: 'Your baby is developing language skills rapidly. Narrate your day, read aloud, and sing — it all builds neural connections.', source: 'American Speech-Language-Hearing Association' },
  { id: 6, month: 2, style: 'gentle', topic: 'development', title: 'Watch for Social Smiles', body: 'Around 6–8 weeks, your baby will smile in response to you — not just gas! Mirror their expressions to encourage social development.', source: 'AAP' },
  { id: 7, month: 2, style: 'schedule', topic: 'sleep', title: 'Lengthen Wake Windows', body: 'At 2 months, wake windows are about 60–90 minutes. Watch for sleepy cues (eye rubbing, yawning) to time naps effectively.', source: 'Pediatric Sleep Council' },

  // Month 3
  { id: 8, month: 3, style: 'gentle', topic: 'motor', title: 'Tummy Time Every Day', body: 'Aim for 30 minutes of tummy time spread throughout the day to build neck, shoulder, and core strength.', source: 'AAP' },
  { id: 9, month: 3, style: 'gentle', topic: 'development', title: 'Follow Their Lead', body: 'Your baby is becoming more alert and curious. Let them guide play — if they look away, they need a break. Follow their cues.', source: 'Zero to Three' },
  { id: 10, month: 3, style: 'schedule', topic: 'sleep', title: 'Consistent Nap Locations', body: 'Napping in the same safe sleep space helps your baby associate the environment with sleep, making naps easier over time.', source: 'AAP' },
  { id: 21, month: 3, style: 'gentle', topic: 'teething', title: 'Early Teething Signs', body: 'Teething can start as early as 3 months. Watch for increased drooling, mouthing everything, and fussiness. No teeth yet — but the process has begun.', source: 'AAP' },
  { id: 22, month: 3, style: 'schedule', topic: 'teething', title: 'Drool Rash Prevention', body: 'Heavy drooling from early teething can cause chin rashes. Gently pat dry (don\'t rub) and apply a thin barrier cream to protect sensitive skin.', source: 'AAP' },

  // Month 4
  { id: 11, month: 4, style: 'gentle', topic: 'sleep', title: 'Sleep Training: Gentle Start', body: 'The 4-month sleep regression is real. Gentle methods like the "Fading" approach gradually reduce your presence at bedtime without letting baby cry alone.', source: 'AAP' },
  { id: 12, month: 4, style: 'gentle', topic: 'development', title: 'Babble Back', body: 'When your baby coos and babbles, respond! These "serve and return" interactions are the foundation of language and emotional development.', source: 'Harvard Center on the Developing Child' },
  { id: 13, month: 4, style: 'schedule', topic: 'sleep', title: 'Bedtime Routine Now', body: 'Start a consistent 4-step bedtime routine (e.g., bath, feed, song, sleep). Consistency at this age begins to train the sleep association.', source: 'Pediatric Sleep Council' },
  { id: 14, month: 4, style: 'schedule', topic: 'sleep', title: 'Dropping to 3-4 Naps', body: 'Most 4-month-olds do best on 3–4 naps per day with wake windows of 1.5–2 hours. Overtiredness makes night sleep harder.', source: 'Pediatric Sleep Council' },
  { id: 23, month: 4, style: 'gentle', topic: 'teething', title: 'Safe Teething Toys', body: 'Offer firm silicone or rubber teething toys — avoid liquid-filled or frozen hard rings. Cold (not frozen) teethers can soothe sore gums safely.', source: 'AAP' },
  { id: 24, month: 4, style: 'schedule', topic: 'teething', title: 'Teething vs. Illness', body: 'Teething may cause mild fussiness and drooling but should NOT cause high fever or diarrhea. If those appear, it\'s likely illness — call your pediatrician.', source: 'AAP' },

  // Month 5
  { id: 15, month: 5, style: 'gentle', topic: 'sleep', title: 'Introduce a Lovey', body: 'A small, safe comfort object (once baby can roll both ways) can become a soothing anchor for sleep — great for gentle sleep approaches.', source: 'AAP' },
  { id: 16, month: 5, style: 'gentle', topic: 'motor', title: 'Supported Sitting Play', body: 'Use pillows to help baby sit upright for play. This builds core strength and spatial awareness ahead of independent sitting.', source: 'AAP' },
  { id: 17, month: 5, style: 'schedule', topic: 'feeding', title: 'Start Solid Food Prep', body: 'Talk to your pediatrician now about starting solids at 6 months. Signs of readiness: sits with support, shows interest in food, lost tongue-thrust reflex.', source: 'WHO / AAP' },
  { id: 25, month: 5, style: 'gentle', topic: 'teething', title: 'Gum Massage', body: 'Gently rub your baby\'s gums with a clean finger for 1–2 minutes. The counter-pressure relieves teething discomfort and many babies find it calming.', source: 'AAP' },
  { id: 26, month: 5, style: 'schedule', topic: 'teething', title: 'When to Use Pain Relief', body: 'If teething is disrupting sleep or feeding, ask your pediatrician about infant acetaminophen (Tylenol). Avoid teething gels with benzocaine — not safe for infants.', source: 'FDA / AAP' },

  // Month 6
  { id: 18, month: 6, style: 'gentle', topic: 'feeding', title: 'Baby-Led Introduction to Solids', body: 'Baby-led weaning lets your baby self-feed soft, appropriately sized foods. It builds motor skills and a healthy relationship with food.', source: 'WHO' },
  { id: 19, month: 6, style: 'gentle', topic: 'development', title: 'Separation Anxiety is Normal', body: 'Mild stranger anxiety starting around 6 months is a sign of healthy attachment. Stay close and reassure — this phase passes.', source: 'Zero to Three' },
  { id: 20, month: 6, style: 'schedule', topic: 'sleep', title: 'Transition to 3 Naps', body: 'Most 6-month-olds are ready to consolidate to 3 naps with wake windows of 2–2.5 hours. Predictable timing supports better night sleep.', source: 'Pediatric Sleep Council' },
  { id: 27, month: 6, style: 'gentle', topic: 'teething', title: 'First Tooth Care', body: 'Once the first tooth appears, start brushing with a soft infant toothbrush and a rice-grain amount of fluoride toothpaste. Make it a fun routine, not a fight.', source: 'AAP / ADA' },
  { id: 28, month: 6, style: 'schedule', topic: 'teething', title: 'First Dental Visit', body: 'Schedule your baby\'s first dental visit within 6 months of the first tooth appearing, or by their first birthday — whichever comes first.', source: 'American Academy of Pediatric Dentistry' },

  // Month 7
  { id: 29, month: 7, style: 'gentle', topic: 'sleep', title: 'Honor Sleepy Cues', body: 'At 7 months, wake windows stretch to about 2.5–3 hours. Watch for eye rubbing and quieting — putting baby down before overtired makes settling much easier.', source: 'Pediatric Sleep Council' },
  { id: 30, month: 7, style: 'schedule', topic: 'sleep', title: 'Consolidating to 2–3 Naps', body: 'Most 7-month-olds do well on 3 naps, with a move toward 2 naps on the horizon. Keep a consistent morning wake time to anchor the schedule.', source: 'Pediatric Sleep Council' },
  { id: 31, month: 7, style: 'gentle', topic: 'feeding', title: 'Prioritize Iron-Rich Foods', body: 'Breast milk iron stores begin to deplete around 6–7 months. Offer iron-rich purées — pureed meats, lentils, or iron-fortified cereals — at least once daily.', source: 'AAP' },
  { id: 32, month: 7, style: 'schedule', topic: 'feeding', title: 'Two Solid Meals a Day', body: 'By 7 months, aim for two small solid meals alongside milk feeds. Keep portions small — milk is still the primary nutrition source at this age.', source: 'WHO / AAP' },
  { id: 33, month: 7, style: 'gentle', topic: 'development', title: 'Object Permanence is Clicking', body: 'Your baby now understands that things exist even when hidden. Peek-a-boo and hide-the-toy games are developmentally perfect right now — and endlessly entertaining.', source: 'Zero to Three' },
  { id: 34, month: 7, style: 'schedule', topic: 'development', title: 'Predictable Routines Build Confidence', body: 'Consistent daily routines help babies predict what comes next, reducing fussiness and building a sense of security. Narrate the routine as you go.', source: 'Zero to Three' },
  { id: 35, month: 7, style: 'gentle', topic: 'motor', title: 'Sitting Independently', body: 'Many babies sit unsupported around 7 months. Surround them with soft pillows and let them reach for toys — controlled toppling builds balance and core strength.', source: 'AAP' },
  { id: 36, month: 7, style: 'schedule', topic: 'motor', title: 'Floor Time Every Day', body: 'Aim for at least 30 minutes of supervised floor time daily. Reaching, rolling, and early crawling movements are best developed without bouncers or seats.', source: 'AAP' },

  // Month 8
  { id: 37, month: 8, style: 'gentle', topic: 'sleep', title: 'Separation Anxiety Affects Sleep', body: 'Separation anxiety peaks around 8–10 months and often disrupts previously good sleep. Extra reassurance at bedtime — a longer cuddle, an extra song — is appropriate and temporary.', source: 'Zero to Three' },
  { id: 38, month: 8, style: 'schedule', topic: 'sleep', title: 'Protect the Morning Nap', body: 'The morning nap anchors the rest of the day at this age. Keep the first wake window to about 2.5–3 hours and don\'t let the morning nap run too long or it will push bedtime.', source: 'Pediatric Sleep Council' },
  { id: 39, month: 8, style: 'gentle', topic: 'feeding', title: 'Introducing Soft Finger Foods', body: 'Soft, dissolvable finger foods like puffs, ripe banana pieces, or well-cooked carrot pieces help develop the pincer grasp and self-feeding confidence. Stay close and watch.', source: 'AAP' },
  { id: 40, month: 8, style: 'schedule', topic: 'feeding', title: 'Introduce an Open Cup', body: 'Start offering small sips of water in an open or straw cup at mealtimes. Early cup practice now makes the bottle-to-cup transition at 12 months much smoother.', source: 'AAP' },
  { id: 41, month: 8, style: 'gentle', topic: 'development', title: 'Cause-and-Effect Play', body: 'Toys that respond to baby\'s actions — buttons that light up, stacking cups, simple drums — teach cause and effect and hold attention far longer than passive toys.', source: 'Zero to Three' },
  { id: 42, month: 8, style: 'schedule', topic: 'development', title: 'Daily Book Reading', body: 'Reading the same books repeatedly isn\'t boring to your baby — it\'s how they learn. Babies this age love board books with faces, animals, and simple patterns.', source: 'AAP Literacy Task Force' },
  { id: 43, month: 8, style: 'gentle', topic: 'motor', title: 'Crawling on Their Own Timeline', body: 'Some babies skip crawling entirely and move straight to walking — both are normal. What matters is that baby is moving and exploring. Don\'t rush or compare.', source: 'AAP' },
  { id: 44, month: 8, style: 'schedule', topic: 'motor', title: 'Encourage Reaching and Reaching Far', body: 'Place toys just out of reach during floor time to motivate movement. This builds the arm strength and coordination needed for crawling and pulling up.', source: 'AAP' },

  // Month 9
  { id: 45, month: 9, style: 'gentle', topic: 'sleep', title: 'Night Waking Is Still Normal', body: 'Many 9-month-olds still wake once at night. If it\'s one wake-up and everyone is coping, it may not need "fixing." Biological night waking at this age is well within normal range.', source: 'AAP' },
  { id: 46, month: 9, style: 'schedule', topic: 'sleep', title: 'Moving Toward 2 Naps', body: 'If your 9-month-old is fighting the third nap consistently, it may be time to drop to 2 naps. Lengthen wake windows to about 3 hours between naps.', source: 'Pediatric Sleep Council' },
  { id: 47, month: 9, style: 'gentle', topic: 'feeding', title: 'Expand Textures, Not Just Flavors', body: 'By 9 months, offer mashed, minced, and soft lumpy textures — not just purées. Babies who experience varied textures early are less likely to become selective eaters.', source: 'WHO' },
  { id: 48, month: 9, style: 'schedule', topic: 'feeding', title: 'Three Meals, Two Snacks', body: 'Work toward a rhythm of three small solid meals and one or two snacks alongside milk feeds. Predictable meal timing helps regulate hunger cues.', source: 'AAP' },
  { id: 49, month: 9, style: 'gentle', topic: 'development', title: 'They Understand More Than They Can Say', body: 'At 9 months, babies understand simple words like their name and "no" — even if they can\'t say them. Keep narrating, naming, and responding to their sounds.', source: 'American Speech-Language-Hearing Association' },
  { id: 50, month: 9, style: 'schedule', topic: 'development', title: 'Point and Name Everything', body: 'Pointing at objects and naming them is one of the most powerful language-building habits at this age. Every outing is a vocabulary lesson.', source: 'American Speech-Language-Hearing Association' },
  { id: 51, month: 9, style: 'gentle', topic: 'motor', title: 'Pulling to Stand', body: 'Baby will start using furniture to pull themselves upright. Let them — it\'s important weight-bearing practice. Lower the crib mattress to the lowest setting now if you haven\'t already.', source: 'AAP' },
  { id: 52, month: 9, style: 'schedule', topic: 'motor', title: 'Create a Safe Exploration Zone', body: 'Baby-proof a defined area and let your baby move freely without constant redirection. Uninterrupted exploration builds motor confidence and problem-solving skills.', source: 'Zero to Three' },

  // Month 10
  { id: 53, month: 10, style: 'gentle', topic: 'sleep', title: 'Sleep Regressions Can Return', body: 'The 8–10 month period often brings another sleep disruption tied to developmental leaps. Ride it out with consistent routines — it typically resolves within 2–4 weeks.', source: 'Pediatric Sleep Council' },
  { id: 54, month: 10, style: 'schedule', topic: 'sleep', title: 'Aim for 11–14 Hours Total', body: 'At 10 months, most babies need 10–12 hours overnight and 2–3 hours of daytime napping. Protect total sleep by keeping an early, consistent bedtime.', source: 'AAP' },
  { id: 55, month: 10, style: 'gentle', topic: 'feeding', title: 'Let Them Make a Mess', body: 'Self-feeding is messy — and important. Babies who are allowed to explore food with their hands are building sensory tolerance and fine motor skills. Put a mat under the high chair and let go.', source: 'WHO' },
  { id: 56, month: 10, style: 'schedule', topic: 'feeding', title: 'Structured Snack Times', body: 'Offer snacks at predictable times rather than grazing throughout the day. This supports hunger regulation and makes mealtimes more successful.', source: 'AAP' },
  { id: 57, month: 10, style: 'gentle', topic: 'development', title: 'Waving and Gesturing Emerge', body: 'Waving bye-bye, clapping, and reaching with intent are early communication milestones. Celebrate and mirror every gesture — it encourages more.', source: 'Zero to Three' },
  { id: 58, month: 10, style: 'schedule', topic: 'development', title: 'Practice Simple Instructions', body: 'Give simple one-step instructions ("Give me the ball") during play. This builds comprehension and primes the brain for following directions.', source: 'American Speech-Language-Hearing Association' },
  { id: 59, month: 10, style: 'gentle', topic: 'motor', title: 'Cruising Along Furniture', body: 'Side-stepping along the couch is called cruising — it\'s how babies prepare for walking. Arrange furniture so they can cruise safely from one piece to another.', source: 'AAP' },
  { id: 60, month: 10, style: 'schedule', topic: 'motor', title: 'Push Toys for Pre-Walkers', body: 'Sturdy push toys (not wheeled walkers with seats — those are not recommended) help babies practice upright walking with support and build leg strength.', source: 'AAP' },

  // Month 11
  { id: 61, month: 11, style: 'gentle', topic: 'sleep', title: 'Nap Resistance Is Normal', body: 'Many 11-month-olds start fighting naps even though they still clearly need them. Stay consistent with timing and routine — the resistance usually passes.', source: 'Pediatric Sleep Council' },
  { id: 62, month: 11, style: 'schedule', topic: 'sleep', title: 'Keep Two Naps for Now', body: 'Most babies aren\'t ready to drop to one nap until 15–18 months. If your 11-month-old seems tired but fights naps, try capping the morning nap to 45–60 minutes.', source: 'Pediatric Sleep Council' },
  { id: 63, month: 11, style: 'gentle', topic: 'feeding', title: 'Eat Together as Much as Possible', body: 'Babies who eat alongside family members at the table are exposed to more varied foods and better eating behaviors. Family meals are one of the strongest influences on long-term eating habits.', source: 'AAP' },
  { id: 64, month: 11, style: 'schedule', topic: 'feeding', title: 'Begin Reducing Nighttime Milk', body: 'If your baby is still feeding overnight, 11 months is a good time to gradually reduce those feeds. They\'re getting enough nutrition during the day and don\'t need night calories.', source: 'AAP' },
  { id: 65, month: 11, style: 'gentle', topic: 'development', title: 'Pointing Is a Major Milestone', body: 'Pointing to share interest (not just to request) is one of the most important early communication milestones. If you\'re not seeing pointing by 12 months, mention it to your pediatrician.', source: 'AAP' },
  { id: 66, month: 11, style: 'schedule', topic: 'development', title: 'Name Games Build Vocabulary', body: 'Play simple name games: "Where\'s your nose? Where\'s Mama\'s nose?" Babies this age love demonstrating what they know and it accelerates vocabulary development.', source: 'American Speech-Language-Hearing Association' },
  { id: 67, month: 11, style: 'gentle', topic: 'motor', title: 'First Steps Are Close', body: 'If your baby is cruising confidently, first steps may be weeks away. Don\'t hold their hands constantly — allow them to stand and balance independently, even if they fall.', source: 'AAP' },
  { id: 68, month: 11, style: 'schedule', topic: 'motor', title: 'Barefoot Is Best Indoors', body: 'Babies learning to walk develop better balance and foot strength in bare feet or soft-soled socks than in hard shoes. Save shoes for outdoor protection.', source: 'AAP' },

  // Month 12
  { id: 69, month: 12, style: 'gentle', topic: 'sleep', title: 'Not Ready to Drop a Nap Yet', body: 'Despite the first birthday milestone, most 12-month-olds still need 2 naps. The move to 1 nap typically happens between 15–18 months. Protect two naps for now.', source: 'Pediatric Sleep Council' },
  { id: 70, month: 12, style: 'schedule', topic: 'sleep', title: 'Total Sleep at 12 Months', body: 'Aim for 11–14 hours of total sleep: 10–12 hours overnight and 2–3 hours across two naps. Consistent bedtime between 6:30–7:30 PM supports the best overnight sleep.', source: 'AAP' },
  { id: 71, month: 12, style: 'gentle', topic: 'feeding', title: 'Transitioning to Whole Milk', body: 'At 12 months, you can begin transitioning from formula or breast milk to whole cow\'s milk. Introduce it gradually mixed with familiar milk, and aim for 16–24 oz per day maximum.', source: 'AAP' },
  { id: 72, month: 12, style: 'schedule', topic: 'feeding', title: 'Start Weaning the Bottle', body: 'The AAP recommends weaning off the bottle by 15 months. Start at 12 months by replacing one bottle per day with a cup. Extended bottle use is linked to tooth decay and iron deficiency.', source: 'AAP' },
  { id: 73, month: 12, style: 'gentle', topic: 'development', title: 'First Words Are Here', body: 'Most babies say 1–3 words with meaning by 12 months ("mama," "dada," "ball"). What matters more than quantity is that they\'re intentionally communicating — with words, gestures, and eye contact.', source: 'AAP' },
  { id: 74, month: 12, style: 'schedule', topic: 'development', title: '12-Month Developmental Checklist', body: 'At the 12-month well visit, your pediatrician will check for: waving, pointing, saying 1–2 words, imitating sounds, and responding to their name. Come with questions — it\'s a big appointment.', source: 'AAP' },
  { id: 75, month: 12, style: 'gentle', topic: 'motor', title: 'First Steps on Their Terms', body: 'Some babies walk at 10 months, others at 15 — both are within normal range. Resist comparing. As long as baby is pulling up and cruising, walking will come.', source: 'AAP' },
  { id: 76, month: 12, style: 'schedule', topic: 'motor', title: 'Stair Awareness Begins', body: 'Now that baby is mobile, gate all stairs and begin teaching safe stair navigation — going down feet-first on their belly. This is a skill worth practicing early.', source: 'AAP' },

  // Activities — Month 1
  { id: 101, month: 1, style: 'gentle', topic: 'activity', title: 'Skin-to-Skin Story Time', body: 'Read any book aloud while baby rests on your chest. They can\'t understand the words yet, but your voice, heartbeat, and warmth together are deeply calming and stimulating.', source: 'Zero to Three' },
  { id: 102, month: 1, style: 'schedule', topic: 'activity', title: 'Tummy Time Windows', body: 'Work 2–3 short tummy time sessions (2–3 minutes each) into wake windows. Place a rolled towel under their chest and get down at eye level to hold their attention.', source: 'AAP' },

  // Activities — Month 2
  { id: 103, month: 2, style: 'gentle', topic: 'activity', title: 'High-Contrast Card Gazing', body: 'Hold a black-and-white pattern card 8–12 inches from baby\'s face and slowly move it side to side. Newborn vision is tuned to high contrast — watch their eyes lock on and follow.', source: 'Zero to Three' },
  { id: 104, month: 2, style: 'schedule', topic: 'activity', title: 'Song-and-Wind-Down Ritual', body: 'Pick two songs and sing them in the same order before every nap and bedtime. The repetition starts building a sleep association that pays off in the weeks ahead.', source: 'Pediatric Sleep Council' },

  // Activities — Month 3
  { id: 105, month: 3, style: 'gentle', topic: 'activity', title: 'Baby Gym Batting', body: 'Lay baby under a play gym and guide their hand to swipe at a hanging toy. Once they feel it move and make noise, the lightbulb moment — "I did that!" — is visible on their face.', source: 'Zero to Three' },
  { id: 106, month: 3, style: 'schedule', topic: 'activity', title: 'Kick-and-Splash Bath Play', body: 'During bath time, let baby kick freely in warm shallow water. The splashing delights them and the leg movement builds the strength they\'ll need for rolling and crawling.', source: 'AAP' },

  // Activities — Month 4
  { id: 107, month: 4, style: 'gentle', topic: 'activity', title: 'Peek-a-Boo with a Scarf', body: 'Cover your face with a soft scarf, then whisk it away. At 4 months this is pure comedy to them. The suspense and reveal lights up the exact circuits that object permanence will grow from.', source: 'Zero to Three' },
  { id: 108, month: 4, style: 'schedule', topic: 'activity', title: 'Rattle Sound Tracking', body: 'Shake a rattle to baby\'s left, then right, then above — making them turn their head to find the source. It\'s a workout for neck muscles and an early listening skill all in one.', source: 'AAP' },

  // Activities — Month 5
  { id: 109, month: 5, style: 'gentle', topic: 'activity', title: 'Lap Bounce Rhymes', body: 'Sit baby on your lap facing you and bounce gently to a nursery rhyme. After a few rounds they\'ll start leaning forward in anticipation of the bounce. That anticipation is early humor.', source: 'Zero to Three' },
  { id: 110, month: 5, style: 'schedule', topic: 'activity', title: 'Reach-and-Grab Line-Up', body: 'Lay 3–4 different toys in a row just within reach during floor time. Let baby work their way down the line. The effort of reaching and grabbing each one builds fine motor skills fast.', source: 'AAP' },

  // Activities — Month 6
  { id: 111, month: 6, style: 'gentle', topic: 'activity', title: 'Water Sensory Play', body: 'Fill a shallow container with a little warm water and let baby splash their hands (you right there, always). The sensation is endlessly fascinating and the mess is 100% worth it.', source: 'Zero to Three' },
  { id: 112, month: 6, style: 'schedule', topic: 'activity', title: 'First Food Exploration', body: 'Before the spoon comes out, let baby touch, squeeze, and smell a small piece of soft food. Positive early sensory exposure to food is one of the strongest predictors of a good eater later.', source: 'WHO / AAP' },

  // Activities — Month 7
  { id: 113, month: 7, style: 'gentle', topic: 'activity', title: 'Hide the Toy', body: 'Slowly hide a favorite toy under a blanket while baby watches. Pause. Let them find it. Object permanence is clicking right now and their delight at finding it every time never gets old.', source: 'Zero to Three' },
  { id: 114, month: 7, style: 'schedule', topic: 'activity', title: 'Fill and Dump Containers', body: 'Give baby a cup and a small pile of large soft balls or blocks. Show them how to drop one in, then dump it out. This loop will occupy them far longer than any electronic toy.', source: 'Zero to Three' },

  // Activities — Month 8
  { id: 115, month: 8, style: 'gentle', topic: 'activity', title: 'Dance to Different Tempos', body: 'Play a slow song, then a fast one, moving baby\'s arms and swaying with them to each. Babies this age respond visibly to rhythm changes — it\'s musical training disguised as fun.', source: 'Zero to Three' },
  { id: 116, month: 8, style: 'schedule', topic: 'activity', title: 'Ball Roll Back and Forth', body: 'Sit facing baby on the floor, legs apart, and roll a soft ball toward them. Guide their hands to push it back. This is their very first turn-taking game — a huge social milestone.', source: 'Zero to Three' },

  // Activities — Month 9
  { id: 117, month: 9, style: 'gentle', topic: 'activity', title: 'Cardboard Box World', body: 'Give baby a large empty box to crawl into and explore. Add a soft toy inside. The novelty of an enclosed space is genuinely thrilling to a 9-month-old and costs exactly nothing.', source: 'Zero to Three' },
  { id: 118, month: 9, style: 'schedule', topic: 'activity', title: 'Simple Obstacle Course', body: 'Arrange a row of cushions, a tunnel made of blankets, and a toy at the end. Guide baby through it. The structured challenge builds crawling confidence and problem-solving.', source: 'AAP' },

  // Activities — Month 10
  { id: 119, month: 10, style: 'gentle', topic: 'activity', title: 'Edible Finger Painting', body: 'Mix plain yogurt with a little mashed berry on a tray and let baby paint freely. It\'s edible, washable, and produces some of the best baby photos you\'ll ever take.', source: 'Zero to Three' },
  { id: 120, month: 10, style: 'schedule', topic: 'activity', title: 'Push-and-Chase Game', body: 'Push a soft ball across the floor and let baby crawl after it. Once they reach it, guide them to push it back toward you. Short, structured rounds of this build motor skills and anticipation.', source: 'AAP' },

  // Activities — Month 11
  { id: 121, month: 11, style: 'gentle', topic: 'activity', title: 'Outdoor Texture Walk', body: 'Take a slow walk and stop to let baby touch leaves, grass, bark, and smooth stones. Let them lead. Nature provides more sensory variety than any toy store, and fresh air helps everyone.', source: 'Zero to Three' },
  { id: 122, month: 11, style: 'schedule', topic: 'activity', title: 'One-Piece Knob Puzzle', body: 'Introduce a simple single-piece knob puzzle. Show baby how to lift and replace the piece. It takes patience but the concentration on their face — and eventual triumph — is worth every attempt.', source: 'AAP' },

  // Activities — Month 12
  { id: 123, month: 12, style: 'gentle', topic: 'activity', title: 'Discovery Basket', body: 'Fill a basket with 6–8 safe objects of different textures — a wooden ring, a soft ball, a silicone spoon, a fabric square. Let baby empty and investigate it all. Simple, endlessly replayable.', source: 'Zero to Three' },
  { id: 124, month: 12, style: 'schedule', topic: 'activity', title: 'Stacking Tower Challenge', body: 'Stack 3 soft foam blocks in front of baby and let them knock it down. Then stack them again. Show them how to add a block. The back-and-forth of build-and-destroy is perfect 12-month play.', source: 'Zero to Three' },

  // ── FUSSY PHASE (months 1–12) ──────────────────────────────────────────────
  { id: 200, month: 1, style: 'gentle', topic: 'fussy', title: 'The 5 S\'s for Fussy Newborns', body: 'Swaddle, side/stomach hold, shush, swing, and suck calm most newborns within minutes. Work through them in order — the combination is far more powerful than any one alone.', source: 'Dr. Harvey Karp / AAP' },
  { id: 201, month: 1, style: 'schedule', topic: 'fussy', title: 'Track the Witching Hour', body: 'Most newborns have a predictable fussy window — often 5–9 PM. Logging it for 3 days turns a frightening mystery into a known event you can prepare for.', source: 'AAP' },
  { id: 202, month: 2, style: 'gentle', topic: 'fussy', title: 'The 6-Week Peak', body: 'Fussiness peaks around 6 weeks and then begins to ease. If you\'re in the thick of it right now, you\'re likely at the worst of it — it gets easier from here.', source: 'AAP' },
  { id: 203, month: 2, style: 'schedule', topic: 'fussy', title: 'Overtiredness Amplifies Fussiness', body: 'At 2 months, wake windows are only 60–90 minutes. Even 20 extra minutes of wakefulness can tip a baby into overtiredness that makes the next few hours miserable.', source: 'Pediatric Sleep Council' },
  { id: 204, month: 3, style: 'gentle', topic: 'fussy', title: '3-Month Growth Spurt', body: 'Around 3 months many babies hit a growth spurt that drives extra hunger and fussiness for 3–5 days. Feed more, rest more, and know it passes quickly.', source: 'AAP' },
  { id: 205, month: 3, style: 'schedule', topic: 'fussy', title: 'Stimulation Overload', body: 'At 3 months babies are more alert and overstimulate easily. If fussiness spikes after busy environments, dim the lights and reduce noise for 20 minutes — it\'s often all they need.', source: 'Zero to Three' },
  { id: 206, month: 4, style: 'gentle', topic: 'fussy', title: '4-Month Fussiness Is Real', body: 'The 4-month regression changes sleep cycles permanently and the exhaustion it causes makes everything harder. Extra contact, babywearing, and patience are your best tools right now.', source: 'AAP' },
  { id: 207, month: 4, style: 'schedule', topic: 'fussy', title: 'Predictability Reduces Fussiness', body: 'Fussy 4-month-olds respond well to consistent routine. A predictable sequence — same order, same cues — reduces the uncertainty that drives a lot of fussiness at this age.', source: 'Pediatric Sleep Council' },
  { id: 208, month: 6, style: 'gentle', topic: 'fussy', title: 'Teething + Leap = Rough Month', body: 'Month 6 often stacks teething discomfort with a developmental leap — a double hit that explains why many moms describe this as one of the harder stretches.', source: 'AAP' },
  { id: 209, month: 6, style: 'schedule', topic: 'fussy', title: 'Hunger Driving Fussiness', body: 'As babies become more active and milk feels less filling, fussiness often spikes around 6 months. If your baby seems perpetually hungry and grumpy, discuss starting solids with your pediatrician.', source: 'WHO / AAP' },
  { id: 210, month: 8, style: 'gentle', topic: 'fussy', title: 'Separation Anxiety Fussiness', body: 'At 8 months, babies understand you exist when you leave — and they\'re not okay with it. The clinginess and upset when you step away is healthy attachment, not a problem to fix.', source: 'Zero to Three' },
  { id: 211, month: 8, style: 'schedule', topic: 'fussy', title: 'Fussiness Before Milestones', body: 'Babies often get extra fussy in the days before mastering a new skill. If fussiness spiked out of nowhere, watch for a new milestone — crawling, pulling up, a new word — in the next week.', source: 'Zero to Three' },
  { id: 212, month: 9, style: 'gentle', topic: 'fussy', title: 'Night Fussiness: Check Teeth', body: 'Persistent night fussiness at 9 months is often separation anxiety and teething combined. A cold teether and extra bedtime reassurance address both at once.', source: 'AAP' },
  { id: 213, month: 9, style: 'schedule', topic: 'fussy', title: 'Keep Routines Tight During Fussy Phases', body: 'When everything feels off, the schedule is your anchor. Babies going through fussy phases benefit most from knowing exactly what comes next.', source: 'Pediatric Sleep Council' },
  { id: 214, month: 10, style: 'gentle', topic: 'fussy', title: 'Fussiness Around New Skills', body: 'Cruising and early walking attempts are physically demanding and frustrating. Fussiness at 10 months is often a baby working very hard to do something new.', source: 'AAP' },
  { id: 215, month: 10, style: 'schedule', topic: 'fussy', title: 'Shorten Wake Windows During Fussy Spells', body: 'During fussy or regressive periods, temporarily shortening wake windows by 15–20 minutes reduces overtiredness and often cuts fussiness significantly.', source: 'Pediatric Sleep Council' },
  { id: 216, month: 12, style: 'gentle', topic: 'fussy', title: '12-Month Fussiness Is a Transition', body: 'Many babies become more emotional and clingy around their first birthday as mobility, sleep changes, and a developmental leap all collide. It\'s developmental, and it passes.', source: 'Zero to Three' },
  { id: 217, month: 12, style: 'schedule', topic: 'fussy', title: 'Hunger Fussiness Shifts at 12 Months', body: 'As milk intake naturally drops and solid food increases, some 12-month-olds become fussy at mealtimes. Three meals and 1–2 snacks on a predictable schedule helps regulate hunger cues.', source: 'AAP' },

  // ── DEVELOPMENT LEAP (months 1–12) ────────────────────────────────────────
  { id: 220, month: 1, style: 'gentle', topic: 'leap', title: 'Leap 1: Waking Up to the World', body: 'Around 5 weeks, your baby\'s senses sharpen suddenly — they see more, hear more, feel more. This sensory flood causes fussiness but also the first real signs of alertness and engagement.', source: 'The Wonder Weeks' },
  { id: 221, month: 1, style: 'schedule', topic: 'leap', title: 'Supporting Leap 1', body: 'During the first leap, predictable feeding and sleep windows become even more important. A fussy newborn who is also overstimulated needs fewer inputs, not more.', source: 'The Wonder Weeks' },
  { id: 222, month: 2, style: 'gentle', topic: 'leap', title: 'Leap 2: Discovering Patterns', body: 'Around 8 weeks, your baby starts recognizing patterns — the shape of your face, the rhythm of your voice. This is why they suddenly stare at things with intense, focused concentration.', source: 'The Wonder Weeks' },
  { id: 223, month: 2, style: 'schedule', topic: 'leap', title: 'Leap 2 and Feed Frequency', body: 'Leap 2 often triggers cluster-feeding that can last a week. This is appetite-driven — the brain is demanding extra energy for rapid development. Feed on demand and know it\'s temporary.', source: 'The Wonder Weeks' },
  { id: 224, month: 3, style: 'gentle', topic: 'leap', title: 'Leap 3: Smooth Transitions', body: 'Around 12 weeks, babies grasp the concept of smooth movement and transitions. Watch their eyes track a moving object with new fluidity — that\'s the leap in action.', source: 'The Wonder Weeks' },
  { id: 225, month: 3, style: 'schedule', topic: 'leap', title: 'The Golden Period After Leap 3', body: 'After Leap 3, many parents describe a calmer, more settled period. Use this window to establish a firmer schedule before Leap 4 arrives around 19 weeks.', source: 'The Wonder Weeks' },
  { id: 226, month: 4, style: 'gentle', topic: 'leap', title: 'Leap 4: Understanding Events', body: 'Leap 4, around 19 weeks, is the biggest so far — baby grasps that events have a beginning, middle, and end. This cognitive jump is what makes the 4-month sleep regression so significant.', source: 'The Wonder Weeks' },
  { id: 227, month: 4, style: 'schedule', topic: 'leap', title: 'Leap 4 Is the Longest', body: 'Leap 4 lasts 4–5 weeks and is the most disruptive leap to date. Your schedule is the anchor that gets you through — don\'t abandon it because it feels harder.', source: 'The Wonder Weeks' },
  { id: 228, month: 5, style: 'gentle', topic: 'leap', title: 'Between Leaps: Use the Window', body: 'Month 5 often falls between leaps — a calmer, more settled period. Use this window to enjoy your baby and solidify any sleep habits before Leap 5 arrives around 26 weeks.', source: 'The Wonder Weeks' },
  { id: 229, month: 5, style: 'schedule', topic: 'leap', title: 'Leap 5 Approaching', body: 'Leap 5 begins around 26 weeks — you may notice your baby becoming clingier and fussier in the run-up. Tighten the schedule and front-load connection time during the day.', source: 'The Wonder Weeks' },
  { id: 230, month: 6, style: 'gentle', topic: 'leap', title: 'Leap 5: The World of Relationships', body: 'During Leap 5, babies grasp relationships between things — inside, on top of, far from. This is why peek-a-boo suddenly gets hilarious and object permanence starts clicking.', source: 'The Wonder Weeks' },
  { id: 231, month: 6, style: 'schedule', topic: 'leap', title: 'Protecting Sleep During Leap 5', body: 'Leap 5 is notorious for disrupting naps. Keep nap windows consistent and resist keeping baby awake longer thinking it will help — overtiredness makes any leap harder to get through.', source: 'The Wonder Weeks' },
  { id: 232, month: 8, style: 'gentle', topic: 'leap', title: 'Leap 6: The World of Categories', body: 'Around 37 weeks, babies start sorting the world into categories — animals vs objects, familiar vs strangers. This is the brain behind their sudden strong opinions about everything.', source: 'The Wonder Weeks' },
  { id: 233, month: 8, style: 'schedule', topic: 'leap', title: 'Clinging During Leap 6', body: 'Leap 6 can make babies clingy in ways that disrupt even well-established schedules. A consistent daily rhythm provides the security they need to tolerate separation during this leap.', source: 'The Wonder Weeks' },
  { id: 234, month: 10, style: 'gentle', topic: 'leap', title: 'Leap 7: Understanding Sequences', body: 'Around 46 weeks, babies grasp sequences — actions happen in order to achieve a goal. This is why they suddenly love putting things in and out of containers and pulling everything off shelves.', source: 'The Wonder Weeks' },
  { id: 235, month: 10, style: 'schedule', topic: 'leap', title: 'Channeling Leap 7 Energy', body: 'Leap 7 babies need to DO things. Structure wake windows around cause-and-effect activities — stacking, filling, dumping — to channel their new understanding productively.', source: 'The Wonder Weeks' },
  { id: 236, month: 12, style: 'gentle', topic: 'leap', title: 'Leap 8: Programs', body: 'Around 55 weeks, babies understand that sequences can form flexible programs — skills applied in different ways. Walking, talking, self-feeding are all programs coming online at once.', source: 'The Wonder Weeks' },
  { id: 237, month: 12, style: 'schedule', topic: 'leap', title: 'Surviving Leap 8', body: 'Leap 8 coincides with walking, weaning, and first words — everything feels like chaos simultaneously. Strict consistency in sleep and meal timing is what makes this month manageable.', source: 'The Wonder Weeks' },

  // ── SLEEP REGRESSION (months 1–12) ────────────────────────────────────────
  { id: 240, month: 4, style: 'gentle', topic: 'regression', title: 'The 4-Month Regression Is Permanent', body: 'Unlike other regressions, the 4-month change is neurological and doesn\'t reverse — your baby\'s sleep architecture has permanently matured. The adjustment takes 2–6 weeks and then stabilizes.', source: 'AAP' },
  { id: 241, month: 4, style: 'schedule', topic: 'regression', title: 'Surviving the 4-Month Regression', body: 'The 4-month regression is hardest for schedule-based families because predictability disappears temporarily. Keep wake times consistent even when nights are rough — it\'s the fastest path through.', source: 'Pediatric Sleep Council' },
  { id: 242, month: 6, style: 'gentle', topic: 'regression', title: '6-Month Regression: Less Common', body: 'Not every baby has a 6-month regression, but those who do usually tie it to teething or a leap. Extra feeding, contact, and patience for 1–2 weeks typically resolves it.', source: 'Pediatric Sleep Council' },
  { id: 243, month: 6, style: 'schedule', topic: 'regression', title: 'Check the Schedule First at 6 Months', body: 'If sleep suddenly worsens at 6 months, audit the schedule first — wake windows have stretched to 2–3 hours and an outdated schedule is often the real culprit before it\'s a true regression.', source: 'Pediatric Sleep Council' },
  { id: 244, month: 8, style: 'gentle', topic: 'regression', title: '8-Month Regression: Anxiety-Driven', body: 'The 8–9 month regression is primarily driven by separation anxiety, not a sleep cycle change. Extra reassurance at bedtime — longer cuddles, staying until drowsy — is appropriate and effective.', source: 'Zero to Three' },
  { id: 245, month: 8, style: 'schedule', topic: 'regression', title: 'Don\'t Dismantle the Schedule at 8 Months', body: 'The 8-month regression tempts parents to abandon the routine. Resist — the schedule is the fastest path through. What changes temporarily is the amount of settling support needed, not the structure itself.', source: 'Pediatric Sleep Council' },
  { id: 246, month: 9, style: 'gentle', topic: 'regression', title: 'Riding Out the 9-Month Regression', body: 'The 9-month regression typically lasts 3–6 weeks. Responding warmly to night waking without creating permanent new habits is the gentle parenting balance to strike right now.', source: 'AAP' },
  { id: 247, month: 9, style: 'schedule', topic: 'regression', title: 'One Change at a Time at 9 Months', body: 'If you\'re handling a regression, a nap transition, and new mobility simultaneously, pick the sleep schedule as the one constant. Changing too many things at once prolongs every disruption.', source: 'Pediatric Sleep Council' },
  { id: 248, month: 12, style: 'gentle', topic: 'regression', title: '12-Month Regression: Everything at Once', body: 'The 12-month regression often coincides with a nap transition, new mobility, and first words all at once. It\'s not one thing — it\'s everything changing simultaneously. Extra patience is the prescription.', source: 'Zero to Three' },
  { id: 249, month: 12, style: 'schedule', topic: 'regression', title: 'Earlier Bedtime During the 12-Month Regression', body: 'When 12-month sleep is disrupted, an earlier bedtime (6:00–6:30 PM) is counterintuitive but works. Overtiredness prolongs regressions; banking more overnight sleep breaks the cycle faster.', source: 'Pediatric Sleep Council' },

  // ── MONTHS 13–24 ──────────────────────────────────────────────────────────
  // Month 13
  { id: 300, month: 13, style: 'gentle', topic: 'sleep', title: 'Still Two Naps at 13 Months', body: 'Most 13-month-olds still need 2 naps despite the birthday milestone. Dropping too early leads to overtiredness that disrupts night sleep — hold off until signs of readiness appear at 15–18 months.', source: 'Pediatric Sleep Council' },
  { id: 301, month: 13, style: 'schedule', topic: 'sleep', title: '13-Month Sleep Schedule', body: 'A solid 13-month schedule: wake ~7am, nap 1 at ~9:30am, nap 2 at ~2:30pm, bed at ~7pm. Consistent timing anchors the whole day.', source: 'Pediatric Sleep Council' },
  { id: 302, month: 13, style: 'gentle', topic: 'feeding', title: 'Appetite Dips After the First Birthday', body: 'Growth slows dramatically after 12 months and appetite follows. A toddler who suddenly seems to eat less than they used to is completely normal — their body needs less fuel.', source: 'AAP' },
  { id: 303, month: 13, style: 'schedule', topic: 'feeding', title: 'Three Meals, Two Snacks', body: 'Aim for 3 meals and 2 scheduled snacks daily. Grazing disrupts hunger regulation and makes mealtimes harder — structured eating builds better long-term habits.', source: 'AAP' },
  { id: 304, month: 13, style: 'gentle', topic: 'development', title: 'First Intentional Words', body: 'Most 13-month-olds have 1–3 meaningful words. What matters more than count is intentional communication — using words or gestures purposefully to share and request.', source: 'AAP' },
  { id: 305, month: 13, style: 'schedule', topic: 'development', title: 'Pointing to Share', body: 'Pointing to show you something (not just to ask for it) is one of the most important early milestones. Respond enthusiastically every time — it directly accelerates language development.', source: 'AAP' },
  { id: 306, month: 13, style: 'gentle', topic: 'activity', title: 'Treasure Basket Play', body: 'Fill a basket with 8–10 safe objects of different textures and materials. Let your toddler explore, mouth, and examine freely — unstructured investigation at this age is deeply satisfying.', source: 'Zero to Three' },
  { id: 307, month: 13, style: 'schedule', topic: 'activity', title: 'Ball Games', body: 'Rolling and kicking soft balls with simple turn-taking rules introduces early social game structure. Keep rounds short and celebrate every successful exchange.', source: 'Zero to Three' },
  { id: 308, month: 13, style: 'gentle', topic: 'motor', title: 'First Steps: Wide Stance Is Normal', body: 'New walkers walk with feet wide and arms out for balance — this is perfect form for a beginner. Resist holding their hands constantly; brief independent standing builds balance faster.', source: 'AAP' },
  { id: 309, month: 13, style: 'schedule', topic: 'motor', title: 'Floor Time Still Matters', body: 'Even new walkers need floor time. Crawling, climbing over cushions, and getting up and down strengthens the muscles that make walking stable and confident.', source: 'AAP' },
  { id: 310, month: 13, style: 'gentle', topic: 'leap', title: 'Leap 8 Continues', body: 'Leap 8 (programs) extends into early month 13. Your toddler is learning that skills can be combined and applied flexibly — the cognitive load is enormous, which explains the emotional intensity.', source: 'The Wonder Weeks' },
  { id: 311, month: 13, style: 'gentle', topic: 'fussy', title: 'Post-Birthday Emotional Surge', body: 'Many babies become extra clingy right after their first birthday — Leap 8, new mobility, and schedule changes all collide. More connection time, not less, is the answer.', source: 'Zero to Three' },

  // Month 14
  { id: 312, month: 14, style: 'gentle', topic: 'sleep', title: 'Nap Resistance at 14 Months', body: 'Many 14-month-olds fight naps even though they clearly still need them. A baby who resists but falls asleep quickly once down is not ready to drop the nap.', source: 'Pediatric Sleep Council' },
  { id: 313, month: 14, style: 'schedule', topic: 'sleep', title: 'Cap the Morning Nap', body: 'Keep the morning nap under 45 minutes at 14 months to protect the afternoon nap and bedtime. A long morning nap creates a domino effect that pushes bedtime too late.', source: 'Pediatric Sleep Council' },
  { id: 314, month: 14, style: 'gentle', topic: 'feeding', title: 'Food Refusal Is Normal', body: 'Many 14-month-olds suddenly refuse foods they previously loved. This is normal neophobia, not pickiness — continue offering without pressure, as repeated exposure is how acceptance develops.', source: 'AAP' },
  { id: 315, month: 14, style: 'schedule', topic: 'feeding', title: 'Division of Responsibility', body: 'You decide what, when, and where food is served — your toddler decides whether and how much to eat. Releasing control over intake actually improves it over time.', source: 'Ellyn Satter Institute / AAP' },
  { id: 316, month: 14, style: 'gentle', topic: 'development', title: 'Vocabulary Spurt Coming', body: 'Between 14–18 months most toddlers experience a vocabulary explosion. The more language they hear now — narrated outings, shared books, real conversation — the bigger the spurt.', source: 'American Speech-Language-Hearing Association' },
  { id: 317, month: 14, style: 'schedule', topic: 'development', title: 'Imitation Is Learning', body: 'At 14 months, toddlers imitate everything — stirring a bowl, wiping a surface, talking on a toy phone. Give them safe duplicates of household objects to imitate with.', source: 'Zero to Three' },
  { id: 318, month: 14, style: 'gentle', topic: 'activity', title: 'Pretend Play Begins', body: 'A baby doll, a toy spoon, or a small blanket introduces the first pretend play — feeding the doll, putting it to sleep. This marks a huge leap in imagination and early empathy.', source: 'Zero to Three' },
  { id: 319, month: 14, style: 'schedule', topic: 'activity', title: 'Simple Sorting Games', body: 'Give two containers and a pile of objects in two colors or sizes. Demonstrate sorting and let them attempt it — even rough approximations are developmentally significant at 14 months.', source: 'Zero to Three' },
  { id: 320, month: 14, style: 'gentle', topic: 'motor', title: 'Climbing Everything', body: 'Fourteen-month-olds are compelled to climb. Create one safe climbing option — a low foam step, a small slide — to satisfy the urge constructively rather than just saying no.', source: 'AAP' },
  { id: 321, month: 14, style: 'schedule', topic: 'motor', title: 'Different Surfaces Build Balance', body: 'Walking on grass, carpet, and tile improves balance and proprioception faster than flat floors alone. Daily outdoor walking time is the best gross motor investment at this age.', source: 'AAP' },
  { id: 322, month: 14, style: 'gentle', topic: 'leap', title: 'Leap 9: Principles', body: 'Around 64 weeks (14–15 months), toddlers grasp abstract principles — that rules govern how things and people behave. This is the beginning of limit-testing: not defiance, but science.', source: 'The Wonder Weeks' },

  // Month 15
  { id: 323, month: 15, style: 'gentle', topic: 'sleep', title: '15-Month Sleep Regression', body: 'The 15–18 month regression is one of the most common and disruptive of toddlerhood — driven by leaps, nap transitions, and growing independence. Expect 2–6 weeks before it resolves.', source: 'Pediatric Sleep Council' },
  { id: 324, month: 15, style: 'schedule', topic: 'sleep', title: 'Nap Transition Signs at 15 Months', body: 'Signs of readiness to drop to 1 nap: consistently fighting one nap, taking 45+ minutes to fall asleep, or naps interfering with a reasonable bedtime. Before 15 months, these signs usually mean schedule adjustment, not nap drop.', source: 'Pediatric Sleep Council' },
  { id: 325, month: 15, style: 'gentle', topic: 'feeding', title: 'Toddler Appetite Is Genuinely Small', body: 'Toddler appetite is significantly less than infant appetite — growth has slowed dramatically. A 15-month-old eating what seems like very little is usually completely normal.', source: 'AAP' },
  { id: 326, month: 15, style: 'schedule', topic: 'feeding', title: '15-Month Well Visit: Nutrition Check', body: 'The 15-month checkup is the right time to discuss feeding concerns. Bring a 3-day food diary if you\'re worried — it gives a much more accurate picture than memory alone.', source: 'AAP' },
  { id: 327, month: 15, style: 'gentle', topic: 'development', title: 'Walking and Talking Compete', body: 'Language often stalls while a toddler is mastering walking — the brain prioritizes one skill at a time. Once walking is automatic, expect a language burst.', source: 'American Speech-Language-Hearing Association' },
  { id: 328, month: 15, style: 'schedule', topic: 'development', title: '15-Month Developmental Check', body: 'By 15 months, most toddlers: walk independently, use 3+ words, point to request, wave, and imitate actions. The 15-month well visit screens all of these.', source: 'AAP' },
  { id: 329, month: 15, style: 'gentle', topic: 'activity', title: 'Water Play Outdoors', body: 'A tub of water and some cups outside provides 20–40 minutes of focused play. Pouring, splashing, and observing water is physics learning disguised as the most enjoyable thing possible.', source: 'Zero to Three' },
  { id: 330, month: 15, style: 'schedule', topic: 'activity', title: 'Musical Instruments', body: 'A small drum, xylophone, or shaker lets toddlers make cause-and-effect music on their terms. Ten minutes of music play per day supports rhythm, motor control, and creativity.', source: 'Zero to Three' },
  { id: 331, month: 15, style: 'gentle', topic: 'motor', title: 'Squatting and Rising', body: 'Watch your 15-month-old squat to pick something up and rise again — it\'s effortful but increasingly graceful. This full squat-to-stand is a core strength milestone.', source: 'AAP' },
  { id: 332, month: 15, style: 'schedule', topic: 'motor', title: 'Push-and-Pull Toys', body: 'Push and pull toys encourage confident walking in toddlers still finding their balance. Choose ones stable enough not to tip but light enough to actually push.', source: 'AAP' },
  { id: 333, month: 15, style: 'schedule', topic: 'regression', title: 'What Helps During the 15-Month Regression', body: 'Maintain bedtime routine rigidly even when nights are rough. The routine itself is calming and signals what comes next when everything else feels uncertain.', source: 'Pediatric Sleep Council' },

  // Month 16
  { id: 334, month: 16, style: 'gentle', topic: 'sleep', title: 'Transitioning to One Nap', body: 'If dropping to 1 nap now, place it around 12:00–12:30 PM to bridge the day evenly. Bedtime may need to move earlier (6:00–6:30 PM) for several weeks while the body adjusts.', source: 'Pediatric Sleep Council' },
  { id: 335, month: 16, style: 'schedule', topic: 'sleep', title: 'One-Nap Schedule', body: 'A solid 1-nap schedule: wake ~7am, nap at ~12pm (1.5–2 hrs), bed at ~7pm. The morning wake time is the anchor — keep it consistent, including weekends.', source: 'Pediatric Sleep Council' },
  { id: 336, month: 16, style: 'gentle', topic: 'feeding', title: 'Messy Eating Is Learning', body: 'Mashing food, throwing it, eating with hands — all of this is how toddlers learn about texture, cause and effect, and self-regulation. Deep breaths, a silicone bib, and a floor mat.', source: 'Zero to Three' },
  { id: 337, month: 16, style: 'schedule', topic: 'feeding', title: 'Family Meals Build Better Eaters', body: 'Toddlers who eat with the family are exposed to more food variety and better eating behaviors. Even if they don\'t eat much, sitting together models what eating looks like.', source: 'AAP' },
  { id: 338, month: 16, style: 'gentle', topic: 'development', title: 'Big Emotions, Small Body', body: 'Sixteen-month-olds have adult-sized feelings and infant-sized emotional regulation. Tantrums are a genuinely overwhelmed nervous system — calm presence helps far more than correction.', source: 'Zero to Three' },
  { id: 339, month: 16, style: 'schedule', topic: 'development', title: 'Narrate Emotions', body: 'Name your toddler\'s emotional states out loud: "You\'re frustrated because the block won\'t fit." Narrating emotions builds the vocabulary they\'ll eventually use to express themselves.', source: 'Zero to Three' },
  { id: 340, month: 16, style: 'gentle', topic: 'activity', title: 'Chalk Drawing Outdoors', body: 'Sidewalk chalk lets toddlers draw at full arm extension on a huge canvas. The large strokes are great for shoulder development and spatial awareness — and cleanup is just rain.', source: 'Zero to Three' },
  { id: 341, month: 16, style: 'schedule', topic: 'activity', title: 'Shape Sorter Puzzles', body: 'A 3–4 shape sorter introduces problem-solving, spatial reasoning, and fine motor control. Sit alongside and narrate without solving it for them — the struggle is the point.', source: 'Zero to Three' },
  { id: 342, month: 16, style: 'gentle', topic: 'motor', title: 'Running Starts', body: 'Around 16 months, walking transitions to running — with a lot of falling. Outdoor time on grass softens the inevitable tumbles while building the confidence to keep trying.', source: 'AAP' },
  { id: 343, month: 16, style: 'schedule', topic: 'motor', title: 'Stair Practice', body: 'Practice going up and down stairs with one hand held. This is a safety skill — the sooner they do it confidently, the less dangerous stairs become.', source: 'AAP' },
  { id: 344, month: 16, style: 'gentle', topic: 'teething', title: 'Canine Teething Begins', body: 'The canine teeth typically emerge between 16–20 months and are notoriously painful — longer, sharper roots than other teeth. Cold teethers and extra patience are essential right now.', source: 'AAP' },
  { id: 345, month: 16, style: 'schedule', topic: 'teething', title: 'Canine Teething and Sleep', body: 'Canine teething often disrupts sleep that has been solid for months. Ask your pediatrician about acetaminophen or ibuprofen at bedtime during the worst nights.', source: 'AAP' },

  // Month 17
  { id: 346, month: 17, style: 'gentle', topic: 'sleep', title: 'One-Nap Adjustment Period', body: 'The 1-nap transition takes 4–6 weeks to stabilize. During this period your toddler may seem overtired and cranky by late afternoon — an earlier bedtime (6:30 PM) compensates while they adjust.', source: 'Pediatric Sleep Council' },
  { id: 347, month: 17, style: 'schedule', topic: 'sleep', title: 'Protecting Total Sleep at 17 Months', body: 'Toddlers this age need 12–14 hours of total sleep. If the nap is short, move bedtime earlier to compensate. Chronic sleep debt accumulates fast and shows up as tantrums and clinginess.', source: 'AAP' },
  { id: 348, month: 17, style: 'gentle', topic: 'feeding', title: 'Name Every Food', body: 'As language explodes at 17 months, use mealtimes to name every food, color, and texture. "Red tomato, crunchy cracker, soft banana" — food vocabulary accelerates general vocabulary.', source: 'American Speech-Language-Hearing Association' },
  { id: 349, month: 17, style: 'schedule', topic: 'feeding', title: 'Two Scheduled Snacks', body: 'Two scheduled snacks (mid-morning and mid-afternoon) regulate hunger better than grazing. A toddler who snacks constantly is never hungry enough at meals to try new foods.', source: 'AAP' },
  { id: 350, month: 17, style: 'gentle', topic: 'development', title: 'Language Explosion', body: 'Between 17–20 months many toddlers add 2–4 new words per day. The best thing you can do is talk, read, and genuinely listen — respond to every communication attempt.', source: 'American Speech-Language-Hearing Association' },
  { id: 351, month: 17, style: 'schedule', topic: 'development', title: 'Two-Word Combinations', body: 'Most toddlers begin combining two words ("more milk," "daddy go") around 17–20 months. No two-word combinations by 18 months is worth mentioning at the next well visit.', source: 'AAP' },
  { id: 352, month: 17, style: 'gentle', topic: 'activity', title: 'Sensory Bins', body: 'A bin of dried pasta or rice with small cups and spoons provides fine motor work and the deep tactile input that toddlers genuinely crave — and it holds attention for a surprisingly long time.', source: 'Zero to Three' },
  { id: 353, month: 17, style: 'schedule', topic: 'activity', title: 'Simple Art Projects', body: 'Sticker sheets, large crayon scribbling, and finger painting give toddlers creative output in structured 10–15 minute windows. Display their work — it builds pride and motivation to create more.', source: 'Zero to Three' },
  { id: 354, month: 17, style: 'gentle', topic: 'motor', title: 'Kicking a Ball', body: 'Kicking a large ball forward is a new gross motor skill around 17 months. Practice kicking toward a target for balance, coordination, and enormous mutual entertainment.', source: 'AAP' },
  { id: 355, month: 17, style: 'schedule', topic: 'motor', title: 'Throwing with Intent', body: 'Overhead throwing with aim emerges around this age. Play throwing games with soft balls — direct the energy productively before it gets aimed at the furniture.', source: 'AAP' },
  { id: 356, month: 17, style: 'gentle', topic: 'leap', title: 'Leap 10: Systems', body: 'Around 75 weeks (17–18 months), toddlers grasp systems — the world runs on interconnected rules. This is why everything is suddenly "why?" and "mine!" — they\'re mapping the world\'s operating logic.', source: 'The Wonder Weeks' },
  { id: 357, month: 17, style: 'gentle', topic: 'teething', title: 'Canine Teething Peaks', body: 'Canine teeth are often fully erupting around 17–18 months, which is why many parents describe this as the worst teething period of toddlerhood. Cold, firm foods like chilled cucumber provide relief.', source: 'AAP' },

  // Month 18
  { id: 358, month: 18, style: 'gentle', topic: 'sleep', title: '18-Month Sleep Regression', body: 'The 18-month regression is one of the most disruptive of toddlerhood — driven by Leap 10, language explosion, and growing autonomy. Extra patience and consistent routine are the tools that get you through.', source: 'Pediatric Sleep Council' },
  { id: 359, month: 18, style: 'schedule', topic: 'sleep', title: 'Holding the Schedule at 18 Months', body: 'When the 18-month regression hits, keep the schedule rigid even when everything else is chaos. Consistent structure — not giving in to new habits at 2am — is what shortens the regression.', source: 'Pediatric Sleep Council' },
  { id: 360, month: 18, style: 'gentle', topic: 'feeding', title: 'Feeding Power Struggles Peak', body: 'Feeding battles peak around 18 months. The most effective response is to remove emotion from mealtimes — offer, don\'t push, eat your own food with enjoyment, and end meals calmly.', source: 'AAP' },
  { id: 361, month: 18, style: 'schedule', topic: 'feeding', title: 'Cap Milk at 18 Months', body: 'Whole milk should be 16–24 oz max daily — more crowds out solid food intake. If your toddler prefers milk over food, cap it and offer milk only after solid meals.', source: 'AAP' },
  { id: 362, month: 18, style: 'gentle', topic: 'development', title: '18-Month Well Visit', body: 'The 18-month checkup includes a developmental and autism screen. Come prepared to answer: how many words? Does your toddler point to share? Do they follow 2-step instructions?', source: 'AAP' },
  { id: 363, month: 18, style: 'schedule', topic: 'development', title: 'Vocabulary at 18 Months', body: 'Most 18-month-olds say 10–20 words. Fewer than 6–8 words or a vocabulary that isn\'t growing is worth raising at the 18-month visit — early speech therapy is significantly more effective than waiting.', source: 'AAP' },
  { id: 364, month: 18, style: 'gentle', topic: 'activity', title: 'Daily Outdoor Time', body: 'Daily outdoor time — even 20 minutes — dramatically improves sleep, mood, and behavior in 18-month-olds. Nature provides sensory input that no indoor activity fully replicates.', source: 'AAP' },
  { id: 365, month: 18, style: 'schedule', topic: 'activity', title: 'Books With Simple Narratives', body: 'Eighteen-month-olds can follow simple story books with cause-and-effect plots. Reading 3–5 books per day at this age is one of the highest-value activities for language and cognition.', source: 'AAP Literacy Task Force' },
  { id: 366, month: 18, style: 'gentle', topic: 'motor', title: 'Running and Tumbling', body: 'At 18 months, running, stopping, and changing direction all improve rapidly. Unstructured outdoor running play is the best motor development tool — and the best behavioral reset.', source: 'AAP' },
  { id: 367, month: 18, style: 'schedule', topic: 'motor', title: 'Fine Motor Daily Practice', body: 'Pegs in pegboards, large threading beads, and opening/closing containers build the pincer grasp and hand strength that writing will eventually require. Ten minutes daily is plenty.', source: 'AAP' },
  { id: 368, month: 18, style: 'gentle', topic: 'regression', title: '18-Month Regression: You\'re Not Alone', body: 'The 18-month regression affects nearly every family and can last 4–6 weeks. It is temporary and it resolves. Getting through it without creating new sleep crutches is the goal.', source: 'Pediatric Sleep Council' },
  { id: 369, month: 18, style: 'schedule', topic: 'regression', title: 'Define Success During the Regression', body: 'During the 18-month regression, define success as: toddler goes to bed in their own space and settles reasonably. Perfect sleep is not the bar right now — survival is.', source: 'Pediatric Sleep Council' },
  { id: 370, month: 18, style: 'gentle', topic: 'fussy', title: '18-Month Emotional Intensity', body: 'Eighteen-month-olds have more emotions than words to express them. The frustration of wanting to communicate but not being able to drives most meltdowns — every new word they learn reduces the fussiness.', source: 'Zero to Three' },

  // Month 19
  { id: 371, month: 19, style: 'gentle', topic: 'sleep', title: 'Rest Time Without Sleep', body: 'Some 19-month-olds start refusing naps even when exhausted. Try "rest time" in the crib — 60 minutes of quiet even without sleep gives both of you a necessary break.', source: 'Pediatric Sleep Council' },
  { id: 372, month: 19, style: 'schedule', topic: 'sleep', title: 'Hold the Nap at 19 Months', body: 'The average age for dropping the nap is 3 years old. A 19-month-old who fights naps is testing limits, not signaling readiness. A consistent, firm approach holds the nap.', source: 'Pediatric Sleep Council' },
  { id: 373, month: 19, style: 'gentle', topic: 'feeding', title: 'Food Jags Are Normal', body: 'Wanting to eat the same 3 foods for weeks is a completely normal toddler phase. Continue offering variety alongside preferred foods — the jag always ends eventually.', source: 'AAP' },
  { id: 374, month: 19, style: 'schedule', topic: 'feeding', title: 'Spoon Practice at 19 Months', body: 'By 19 months, most toddlers can use a spoon with some success. Offer thick foods (oatmeal, yogurt, mashed potato) that stay on the spoon and let them practice — mess is progress.', source: 'AAP' },
  { id: 375, month: 19, style: 'gentle', topic: 'development', title: 'The "No" Phase', body: 'Saying "no" to everything is a developmental milestone at 19 months — your toddler is discovering autonomy. Offer binary choices ("red cup or blue cup?") to honor independence within safe limits.', source: 'Zero to Three' },
  { id: 376, month: 19, style: 'schedule', topic: 'development', title: 'Two-Step Instructions', body: 'At 19 months, toddlers can follow two-step instructions: "Get your shoes and bring them here." Practice this daily — it builds comprehension, memory, and cooperation all at once.', source: 'American Speech-Language-Hearing Association' },
  { id: 377, month: 19, style: 'gentle', topic: 'activity', title: 'Playdough Exploration', body: 'Non-toxic playdough builds finger strength, creativity, and sustained attention. Let your toddler poke, flatten, and squish freely — structured "making things" comes with time.', source: 'Zero to Three' },
  { id: 378, month: 19, style: 'schedule', topic: 'activity', title: 'Count While You Stack', body: 'Challenge your toddler to build the tallest tower possible. Count the blocks aloud as you stack — gross motor, math, and vocabulary all in one activity.', source: 'Zero to Three' },
  { id: 379, month: 19, style: 'gentle', topic: 'motor', title: 'Walking Backwards', body: 'Many 19-month-olds discover they can walk backwards — watch the intense concentration as they figure it out. Backward locomotion requires sophisticated spatial planning.', source: 'AAP' },
  { id: 380, month: 19, style: 'schedule', topic: 'motor', title: 'Balance Bikes', body: 'Balance bikes (without pedals) develop balance and coordination far better than tricycles at this age. Ten minutes of balance bike time per day is excellent gross motor work.', source: 'AAP' },
  { id: 381, month: 19, style: 'gentle', topic: 'fussy', title: 'Tantrums Are Communication', body: 'Tantrums peak between 18–24 months because big emotions outpace verbal ability. Stay calm, stay close, and narrate after: "That was really hard when we had to leave." Narration builds emotional vocabulary.', source: 'Zero to Three' },

  // Month 20
  { id: 382, month: 20, style: 'gentle', topic: 'sleep', title: 'Bedtime Routine Is the Anchor', body: 'A predictable 20-minute bedtime routine — bath, books, songs, lights out — is the single most powerful sleep tool at this age. Toddlers who know exactly what\'s coming resist bedtime less.', source: 'Pediatric Sleep Council' },
  { id: 383, month: 20, style: 'schedule', topic: 'sleep', title: 'Anticipating Stall Tactics', body: 'Toddlers become expert bedtime stallers around 20 months. Build the stalls into the routine proactively — one extra book, one last drink — before lights out, not as concessions after.', source: 'Pediatric Sleep Council' },
  { id: 384, month: 20, style: 'gentle', topic: 'feeding', title: 'Cook Together', body: 'Let your 20-month-old help wash vegetables or stir batter. Toddlers who participate in food preparation are significantly more likely to try what they helped make.', source: 'AAP' },
  { id: 385, month: 20, style: 'schedule', topic: 'feeding', title: 'New Food Alongside Familiar', body: 'The most effective time to introduce a new food is alongside 2–3 accepted familiar foods. New-alongside-familiar reduces anxiety and increases the chance of at least a taste.', source: 'AAP' },
  { id: 386, month: 20, style: 'gentle', topic: 'development', title: 'Parallel Play', body: 'Twenty-month-olds play beside other children, not with them — this is parallel play and it\'s completely normal. Playing near peers is how social skills develop at this stage.', source: 'Zero to Three' },
  { id: 387, month: 20, style: 'schedule', topic: 'development', title: 'Two-Word Phrases', body: 'By 20 months, most toddlers combine two words regularly. If your toddler isn\'t combining words and has fewer than 10 words total, ask for a speech referral — early is always better.', source: 'AAP' },
  { id: 388, month: 20, style: 'gentle', topic: 'activity', title: 'Imaginative Kitchen Play', body: 'A small toy kitchen or set of pretend food items unlocks hours of imaginative play at 20 months. Accept every pretend meal graciously — you\'re supporting some of the best brain development happening right now.', source: 'Zero to Three' },
  { id: 389, month: 20, style: 'schedule', topic: 'activity', title: 'Matching Games', body: 'Simple matching activities — matching animal cards, matching colored blocks — introduce categorization and hold 20-month-old attention for surprisingly long stretches.', source: 'Zero to Three' },
  { id: 390, month: 20, style: 'gentle', topic: 'motor', title: 'First Jumps', body: 'Most 20-month-olds attempt their first two-foot jump with mixed results. Jumping off the bottom stair or a low foam step is the safest way to practice landing with bent knees.', source: 'AAP' },
  { id: 391, month: 20, style: 'schedule', topic: 'motor', title: 'Stacking 4–6 Blocks', body: 'A 20-month-old should be able to stack 4–6 blocks. If they\'re struggling with 2–3, fine motor play (pegs, threading, playdough) strengthens the hand control needed.', source: 'AAP' },
  { id: 392, month: 20, style: 'gentle', topic: 'teething', title: 'Second Molars Arriving', body: 'Second molars erupt between 20–24 months and are the most painful teeth of toddlerhood — large, with wide flat surfaces. Chilled washcloths to chew and acetaminophen during the worst nights are your best tools.', source: 'AAP' },

  // Month 21
  { id: 393, month: 21, style: 'gentle', topic: 'sleep', title: 'Consistent Wake Time Anchors Everything', body: 'A consistent morning wake time (within 30 minutes every day, weekends included) is the most powerful circadian anchor. It sets the timing for nap, hunger, and bedtime automatically.', source: 'Pediatric Sleep Council' },
  { id: 394, month: 21, style: 'schedule', topic: 'sleep', title: 'Darkness Is a Sleep Tool', body: 'Ensure the sleep environment is fully dark — even small light amounts suppress melatonin in toddlers. Blackout curtains are one of the highest-ROI sleep investments at every age.', source: 'AAP' },
  { id: 395, month: 21, style: 'gentle', topic: 'feeding', title: 'Peer Modeling at Meals', body: 'If you have the opportunity, arrange meals with other toddlers. Children this age are powerful food models for each other — a toddler who sees a peer eating broccoli is significantly more likely to try it.', source: 'AAP' },
  { id: 396, month: 21, style: 'schedule', topic: 'feeding', title: 'Water Between Meals', body: 'If your 21-month-old still wants large amounts of milk and refuses variety, try offering water between meals instead of milk and serving milk only alongside solid meals.', source: 'AAP' },
  { id: 397, month: 21, style: 'gentle', topic: 'development', title: 'Empathy Emerging', body: 'Around 21 months, toddlers begin showing genuine empathy — offering a toy to a crying child, patting a sad face in a book. These moments are the earliest signs of moral development.', source: 'Zero to Three' },
  { id: 398, month: 21, style: 'schedule', topic: 'development', title: 'Spatial Language', body: 'Teach spatial concepts through play: "put it IN the box, now ON the box, now UNDER the box." These relational words are foundational for language complexity and early math thinking.', source: 'American Speech-Language-Hearing Association' },
  { id: 399, month: 21, style: 'gentle', topic: 'activity', title: 'Nature Walk Collections', body: 'Bring a small bag on walks and let your toddler collect rocks, sticks, and leaves. Back home, sort by size or color. Science, math, language, and outdoor time all in one walk.', source: 'Zero to Three' },
  { id: 400, month: 21, style: 'schedule', topic: 'activity', title: 'Knob Puzzles', body: 'A 3–6 piece puzzle with knobs is the right challenge at 21 months. The spatial reasoning required to rotate and fit pieces is foundational for math and problem-solving.', source: 'Zero to Three' },
  { id: 401, month: 21, style: 'gentle', topic: 'motor', title: 'Coordinated Running', body: 'By 21 months, most toddlers run with coordinated arm swing and can stop intentionally — a significant upgrade from the earlier stiff-armed toddler run.', source: 'AAP' },
  { id: 402, month: 21, style: 'schedule', topic: 'motor', title: 'Overhand Throwing Practice', body: 'Practice overhand throwing with a soft ball at a target. The sequence of arm raise, weight shift, and release is genuinely complex — celebrate direction improvement even when aim is wild.', source: 'AAP' },
  { id: 403, month: 21, style: 'gentle', topic: 'teething', title: 'Second Molar Relief', body: 'Second molars erupt in stages — one corner may poke through weeks before the full tooth is out. Cold, chewable food (frozen banana, chilled cucumber) helps more than teethers at this age.', source: 'AAP' },

  // Month 22
  { id: 404, month: 22, style: 'gentle', topic: 'sleep', title: 'Sleep Cements Language', body: 'Language development at 22 months is intense and brain-demanding. Adequate sleep — 12–14 hours total — is directly linked to vocabulary consolidation. Sleep is when new words get cemented.', source: 'AAP' },
  { id: 405, month: 22, style: 'schedule', topic: 'sleep', title: 'Handling Nighttime Fears', body: 'Some toddlers develop nighttime fears around 22 months as imagination outpaces understanding. A small nightlight, a comfort object, and matter-of-fact reassurance handles most fears effectively.', source: 'Zero to Three' },
  { id: 406, month: 22, style: 'gentle', topic: 'feeding', title: 'Shopping as Language Learning', body: 'Let your 22-month-old hold one item in the cart and name it at checkout. Grocery trips as language lessons build vocabulary and positive associations with new foods simultaneously.', source: 'Zero to Three' },
  { id: 407, month: 22, style: 'schedule', topic: 'feeding', title: 'Consistent Meal Timing', body: 'Meals at the same times every day regulate hunger hormones and produce toddlers who arrive at the table actually hungry — which makes everything about feeding easier.', source: 'AAP' },
  { id: 408, month: 22, style: 'gentle', topic: 'development', title: 'Pretend Play Becomes Narrative', body: 'At 22 months, pretend play becomes story-driven — a baby gets sick, goes to the doctor, gets better. These sequences reflect and process real experiences from your toddler\'s life.', source: 'Zero to Three' },
  { id: 409, month: 22, style: 'schedule', topic: 'development', title: 'Concept Vocabulary', body: 'Most 22-month-olds can point to 5–10 body parts. Extend this: "find something blue," "show me something big." Concept vocabulary is the next language frontier.', source: 'American Speech-Language-Hearing Association' },
  { id: 410, month: 22, style: 'gentle', topic: 'activity', title: 'Painting With Brushes', body: 'Upgrade from finger painting to brushes at 22 months. Choosing a brush, dipping it, and applying paint to paper is fine motor work, color exploration, and creative expression.', source: 'Zero to Three' },
  { id: 411, month: 22, style: 'schedule', topic: 'activity', title: 'Simple Memory Games', body: 'Simple 4–6 pair memory card games begin to be accessible at 22 months. Even without fully understanding the rules, the visual matching and turn-taking are developmentally valuable.', source: 'Zero to Three' },
  { id: 412, month: 22, style: 'gentle', topic: 'motor', title: 'Pedaling Begins', body: 'Some 22-month-olds start pedaling a tricycle. The coordination of alternating feet while steering is genuinely hard — give them time on a flat surface with no pressure.', source: 'AAP' },
  { id: 413, month: 22, style: 'schedule', topic: 'motor', title: 'Stairs with Confidence', body: 'Most toddlers step with the same foot on every stair until around 3 years. Safety and confidence on stairs matters more than technique at 22 months — focus on the railing habit.', source: 'AAP' },

  // Month 23
  { id: 414, month: 23, style: 'gentle', topic: 'sleep', title: 'Pre-2-Year Sleep Check', body: 'Before the 2-year regression hits around month 24, audit the sleep environment: fully dark, white noise, comfortable temperature (68–72°F). A strong environment reduces regression impact.', source: 'Pediatric Sleep Council' },
  { id: 415, month: 23, style: 'schedule', topic: 'sleep', title: 'Nap Transition Watch', body: 'Signs the nap drop is coming: consistently 45+ minutes to fall asleep for nap, then refusing bedtime. The average age for dropping the nap is 3 years — hold it as long as possible.', source: 'Pediatric Sleep Council' },
  { id: 416, month: 23, style: 'gentle', topic: 'feeding', title: 'Letting Them Serve Themselves', body: 'A 23-month-old can scoop food from a serving bowl with some help. Giving them agency over what goes on their plate increases willingness to at least taste what they chose.', source: 'Zero to Three' },
  { id: 417, month: 23, style: 'schedule', topic: 'feeding', title: 'Table Manners Are Teachable', body: 'Simple table manners — staying seated, using utensils, not throwing food — are teachable at 23 months with consistent, calm expectations. Model the behavior you want; they\'re watching everything.', source: 'AAP' },
  { id: 418, month: 23, style: 'gentle', topic: 'development', title: 'Emotional Surge Before the Second Birthday', body: 'The weeks before the second birthday often bring more tantrums and emotional intensity. Your toddler is reorganizing emotionally before a major developmental leap — more connection time helps.', source: 'Zero to Three' },
  { id: 419, month: 23, style: 'schedule', topic: 'development', title: 'Three-Word Phrases', body: 'Most 23-month-olds use 3-word phrases ("daddy go bye-bye," "more banana please"). Still primarily using single words at 23 months is worth a speech screening request.', source: 'AAP' },
  { id: 420, month: 23, style: 'gentle', topic: 'activity', title: 'Role Play and Dress-Up', body: 'Simple dress-up — a hat, a bag, adult shoes — sparks role-play that builds social understanding, language, and imagination all at once.', source: 'Zero to Three' },
  { id: 421, month: 23, style: 'schedule', topic: 'activity', title: 'Pattern Recognition', body: 'Make simple AB patterns with blocks ("red, blue, red, blue") and invite your toddler to continue the pattern. This is pre-math thinking developing naturally through play.', source: 'Zero to Three' },
  { id: 422, month: 23, style: 'gentle', topic: 'motor', title: 'Catching With Two Arms', body: 'At 23 months, catching a large soft ball with both arms is beginning to be possible. Practice close range (3 feet) and celebrate the attempt regardless of outcome.', source: 'AAP' },
  { id: 423, month: 23, style: 'schedule', topic: 'motor', title: 'Pencil Grasp Development', body: 'Offer thick crayons for drawing — they naturally encourage the tripod grasp that writing will eventually require. Draw together without directing what they make.', source: 'AAP' },

  // Month 24
  { id: 424, month: 24, style: 'gentle', topic: 'sleep', title: '2-Year Sleep Regression', body: 'The 2-year regression is driven by developmental leaps, new imagination (and new fears), and growing independence. Your toddler hasn\'t forgotten how to sleep — they just need to reconnect with it.', source: 'Pediatric Sleep Council' },
  { id: 425, month: 24, style: 'schedule', topic: 'sleep', title: 'Consistent Limits at 2 Years', body: 'Two-year-olds test every boundary, including sleep ones. Clear, consistent limits — "it\'s sleep time, I\'ll see you in the morning" — with warm follow-through get you through regression faster than negotiating.', source: 'Pediatric Sleep Council' },
  { id: 426, month: 24, style: 'gentle', topic: 'feeding', title: 'Food Autonomy at 2', body: 'Two-year-olds have strong food opinions and that\'s healthy. Respect reasonable preferences while continuing to offer variety — the goal is a competent, curious eater, not a child who eats everything.', source: 'AAP' },
  { id: 427, month: 24, style: 'schedule', topic: 'feeding', title: '2-Year Nutrition Check', body: 'At the 2-year checkup, discuss nutrition: iron (meat, beans, fortified foods), calcium, and vitamin D. These three are the most common shortfalls in toddler diets.', source: 'AAP' },
  { id: 428, month: 24, style: 'gentle', topic: 'development', title: '2-Year Developmental Milestones', body: 'At 2, most toddlers have 50+ words, use 2-word phrases, point to objects in books, and follow 2-step instructions. The 2-year well visit screens all of this — it\'s one of the most important checkpoints.', source: 'AAP' },
  { id: 429, month: 24, style: 'schedule', topic: 'development', title: '2-Year Language Red Flags', body: 'Fewer than 50 words or not combining words at 2 years: request a speech referral — don\'t accept "wait and see." Early speech therapy at 2 has the best outcomes of any age.', source: 'AAP' },
  { id: 430, month: 24, style: 'gentle', topic: 'activity', title: 'Low-Key Second Birthday', body: 'Instead of overwhelming a 2-year-old with many guests and stimulation, a small celebration with 1–2 friends and sensory activities (water, playdough, sandbox) makes for a genuinely joyful day.', source: 'Zero to Three' },
  { id: 431, month: 24, style: 'schedule', topic: 'activity', title: 'Structured Play Dates', body: 'At 2 years, structured play dates — a specific activity, a snack, a defined end time — work better than open-ended ones. Predictable structure makes toddler play dates actually enjoyable.', source: 'Zero to Three' },
  { id: 432, month: 24, style: 'gentle', topic: 'motor', title: 'Jumping With Two Feet', body: 'Most 2-year-olds can jump with both feet leaving the ground. Jumping in puddles, over lines, from low steps — this is the practice that develops and refines the skill.', source: 'AAP' },
  { id: 433, month: 24, style: 'schedule', topic: 'motor', title: 'Tricycle or Balance Bike', body: 'Some 2-year-olds are ready for a tricycle with a push bar; others prefer the balance bike. Either supports motor development — follow their lead on which feels most natural.', source: 'AAP' },
  { id: 434, month: 24, style: 'gentle', topic: 'regression', title: '2-Year Regression: It\'s Developmental', body: 'The 2-year regression happens because your toddler\'s brain is reorganizing around new imagination, autonomy, and emotional complexity. It\'s a sign of development, not a problem with your child or your parenting.', source: 'Pediatric Sleep Council' },
  { id: 435, month: 24, style: 'schedule', topic: 'regression', title: 'Don\'t Stack Changes at 2 Years', body: 'Avoid introducing major changes (new room, potty training, dropping the nap) during the 2-year regression. The regression itself is enough — handle one disruption at a time.', source: 'Pediatric Sleep Council' },
  { id: 436, month: 24, style: 'gentle', topic: 'fussy', title: 'Terrible Twos Are Real', body: 'The "terrible twos" are genuine — intense feelings, limited verbal ability, and a brain that can\'t yet regulate big emotions. Connection before correction is the most effective approach at this age.', source: 'Zero to Three' },
  { id: 437, month: 24, style: 'gentle', topic: 'teething', title: 'Second Molars: Nearly Done', body: 'By 24 months most toddlers have their second molars in or nearly erupted. These are often the most painful — the end of the teething journey is genuinely in sight.', source: 'AAP' },
]

export const funActivities = [
  { id: 'f1', month: 1, topic: 'play', title: 'Dance Party for Two', body: 'Put on your favorite song and sway with your baby. They love the motion and rhythm — and it counts as a workout for you. Bonus: it almost always stops the fussing.' },
  { id: 'f2', month: 2, topic: 'play', title: 'Make Silly Faces', body: 'Stick out your tongue, puff your cheeks, raise your eyebrows — your baby will study every move. Around 6-8 weeks they may even try to copy you. It\'s genuinely hilarious.' },
  { id: 'f3', month: 3, topic: 'play', title: 'Texture Exploration', body: 'Let your baby touch different textures — a soft blanket, a crinkly bag, a cold water bottle. Watch their face light up with each new sensation. Their little reactions are the best.' },
  { id: 'f4', month: 4, topic: 'play', title: 'Baby DJ Session', body: 'Make a playlist of wildly different songs — jazz, pop, classical, your guilty pleasures — and watch your baby\'s reactions. Studies show babies have genuine music preferences, and figuring them out is so fun.' },
  { id: 'f5', month: 5, topic: 'play', title: 'Mirror Play', body: 'Sit your baby in front of a mirror and watch them discover the "other baby." They\'ll smile, reach out, and get totally confused in the best way. Great for self-awareness development too.' },
  { id: 'f6', month: 6, topic: 'play', title: 'Messy Food Painting', body: 'Put a small amount of pureed sweet potato or avocado on their tray and let them go wild. Yes it\'s messy. Yes it\'s absolutely worth it for the photos and the giggles.' },
]

export function getTipsForProfile(month, style, topic = null) {
  return tips.filter(tip =>
    tip.month === month &&
    tip.style === style &&
    (topic === null || tip.topic === topic)
  )
}

export function getFunActivityForMonth(month, topic = null) {
  if (topic !== null && topic !== 'play') return null
  return funActivities.find(a => a.month === month) || null
}

export function getBabyAgeInMonths(dateOfBirth) {
  const dob = new Date(dateOfBirth)
  const today = new Date()
  let months = (today.getFullYear() - dob.getFullYear()) * 12 + (today.getMonth() - dob.getMonth())
  if (today.getDate() < dob.getDate()) months--
  return Math.max(0, months)
}

export function getBabyAgeInWeeks(dateOfBirth) {
  const dob = new Date(dateOfBirth)
  const today = new Date()
  const diffMs = today - dob
  return Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7))
}

export function formatBabyAge(dateOfBirth) {
  const weeks = getBabyAgeInWeeks(dateOfBirth)
  if (weeks < 13) {
    return weeks === 1 ? '1 week old' : `${weeks} weeks old`
  }
  const months = getBabyAgeInMonths(dateOfBirth)
  return months === 1 ? '1 month old' : `${months} months old`
}
